using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using Mono.Cecil;

public static class PendingFilePatcher
{
    // BepInEx 5.x preloader patcher contract: 必须有 TargetDLLs 和 Patch
    public static IEnumerable<string> TargetDLLs { get { yield break; } }
    public static void Patch(AssemblyDefinition assembly) { }

    // 在任何插件 DLL 被加载之前调用
    public static void Initialize()
    {
        try
        {
            string asmPath = Assembly.GetExecutingAssembly().Location;
            string patchersDir = Path.GetDirectoryName(asmPath);
            string bepInExDir = Path.GetDirectoryName(patchersDir);
            string pluginsDir = Path.Combine(bepInExDir, "plugins");
            // 数据文件位于 <游戏根目录>\<xxx_Data>\ModBrowser\Data\（不再使用 BepInEx\ 根目录）
            string gameDir = Path.GetDirectoryName(bepInExDir);
            string dataDir = null;
            string[] dataDirs = Directory.GetDirectories(gameDir, "*_Data");
            if (dataDirs.Length > 0)
                dataDir = Path.Combine(dataDirs[0], "ModBrowser", "Data");
            if (dataDir == null) { Log("*_Data directory not found under " + gameDir); return; }
            string pendingDeletes = Path.Combine(dataDir, "pending_deletes.txt");
            string pendingUpdates = Path.Combine(dataDir, "pending_updates.txt");

            ProcessPendingDeletes(pendingDeletes);
            ProcessPendingUpdates(pendingUpdates, pluginsDir);
        }
        catch (Exception e) { Log("Initialize error: " + e.Message); }
    }

    private static void ProcessPendingDeletes(string filePath)
    {
        if (!File.Exists(filePath)) return;
        var remaining = new List<string>();
        foreach (string line in File.ReadAllLines(filePath))
        {
            string fp = line.Trim();
            if (string.IsNullOrEmpty(fp)) continue;
            if (!File.Exists(fp)) continue;
            try { File.Delete(fp); Log("Deleted: " + fp); }
            catch (Exception e) { Log("Delete failed " + fp + ": " + e.Message); remaining.Add(fp); }
        }
        if (remaining.Count > 0) File.WriteAllLines(filePath, remaining);
        else if (File.Exists(filePath)) File.Delete(filePath);
    }

    private static void ProcessPendingUpdates(string filePath, string pluginsDir)
    {
        if (!File.Exists(filePath)) return;
        var remaining = new List<string>();
        foreach (string line in File.ReadAllLines(filePath))
        {
            string trimmed = line.Trim();
            if (string.IsNullOrEmpty(trimmed)) continue;

            // 格式: mod_id|workshop_path|file1.dll;file2.dll
            string[] parts = trimmed.Split('|');
            if (parts.Length < 3) { remaining.Add(trimmed); continue; }

            string workshopPath = parts[1];
            string[] oldFiles = parts[2].Split(';');

            // 删除旧文件
            bool allDeleted = true;
            foreach (string f in oldFiles)
            {
                string fn = f.Trim();
                if (string.IsNullOrEmpty(fn)) continue;
                string fp = Path.Combine(pluginsDir, fn);
                if (File.Exists(fp))
                {
                    try { File.Delete(fp); Log("Deleted old: " + fn); }
                    catch (Exception e) { Log("Delete old failed " + fn + ": " + e.Message); allDeleted = false; }
                }
            }
            if (!allDeleted) { remaining.Add(trimmed); continue; }

            // 从 workshop 缓存复制新文件
            if (Directory.Exists(workshopPath))
            {
                bool anyCopied = false;
                foreach (string file in Directory.GetFiles(workshopPath, "*", SearchOption.AllDirectories))
                {
                    string rel = file.Substring(workshopPath.Length).TrimStart('\\', '/');
                    string dest = Path.Combine(pluginsDir, rel);
                    try
                    {
                        Directory.CreateDirectory(Path.GetDirectoryName(dest));
                        File.Copy(file, dest, true);
                        anyCopied = true;
                    }
                    catch (Exception e) { Log("Copy failed " + rel + ": " + e.Message); }
                }
                if (anyCopied) Log("Updated mod: " + parts[0]);
                else { remaining.Add(trimmed); continue; }
            }
            else
            {
                Log("Workshop path not found: " + workshopPath);
                remaining.Add(trimmed);
            }
        }
        // 不删除 pending_updates.txt，留给游戏内 ProcessPendingUpdates() 处理
        // （游戏内代码需要读取此文件来更新 installed_mods.json 和 installed_at.json）
    }

    private static void Log(string msg) { Console.WriteLine("[PendingFilePatcher] " + msg); }
}
